(function(){'use strict';const A=DecideAdventure;
const panel=document.createElement('article');panel.className='adventure-panel';panel.id='adventurePanel';$('gameScreen').prepend(panel);
function button(text,action,disabled=false){const b=document.createElement('button');b.textContent=text;b.disabled=disabled;b.onclick=()=>{try{s=action.startsWith('battle:')?A.battle(s,action.slice(7)):A.change(s,action);R.log(s,'บทหัวใจธาร • '+text);save();render();if(s.expedition)EverTaleCombat.launch();}catch(e){status(e.message);}};return b;}
function renderStory(){if(!s.character)return;const w=A.validate(s.adventure);panel.replaceChildren();const title=document.createElement('h2');title.textContent='บทที่ 1 · เสียงเรียกจากหัวใจธาร';const intro=document.createElement('p');intro.textContent='ธารน้ำของหมู่บ้านลานสนกำลังเหือดแห้ง นาราขอให้คุณตามหาร่องรอยในป่ากระซิบ และค้นหาความจริงใต้ภูเขา';panel.append(title,intro);
 const nav=document.createElement('nav');for(const [id,name] of [['village','หมู่บ้านลานสน'],['forest','ป่ากระซิบ'],['cave','ถ้ำหัวใจธาร']]){const b=button(name,'travel:'+id,!!s.expedition||!!s.event||s.dead||id!=='village'&&!w.accepted||id==='cave'&&!w.forest);b.classList.toggle('primary',id===w.location);nav.append(b);}panel.append(nav);
 const text=document.createElement('p');const actions=document.createElement('div');actions.className='adventure-actions';const blocked=!!s.expedition||!!s.event||s.dead;const add=(label,id,disable=false)=>actions.append(button(label,id,blocked||disable));
 if(w.location==='village'){
 text.textContent=w.ending==='restore'?'น้ำกลับมาไหลผ่านหมู่บ้าน นารารักษาศาลาไว้ให้ผู้เดินทางรุ่นต่อไป ลินยินดีที่คุณเลือกช่วยชุมชน':w.ending==='sell'?'คุณขายหัวใจธารให้พ่อค้า ได้เงินมากขึ้น แต่ลำธารยังแห้งและนาราไม่ไว้วางใจคุณเหมือนเดิม':'ตลาดเงียบกว่าที่เคย เสียงลินซ่อมคันธนูดังจากใต้ต้นสน ส่วนนารารออยู่ข้างบ่อน้ำ';
 add('คุยกับนารา','talk:elder');add('คุยกับลิน','talk:lin');add('ถามอีราเรื่องเวท','talk:ira');add('พักที่บ้านรับรอง · 8 ชม.','rest');
 if(w.dialog==='elder'){text.textContent+='\nนารา: '+(w.ending==='restore'?'ขอบคุณที่คืนชีวิตให้ลำธาร บ้านรับรองยินดีต้อนรับคุณเสมอ':w.ending==='sell'?'เงินที่ได้คงมีค่ากับคุณ แต่คนในหมู่บ้านยังต้องออกไปหาน้ำ':w.cave&&!w.claimed?'คุณนำหัวใจธารกลับมาแล้ว จะคืนมันให้ลำธารหรือขายให้พ่อค้า?':w.accepted?'ศาลาเก่าอยู่ลึกเข้าไปในป่า ระวังผู้เฝ้ารากไม้ด้วย':'ช่วยตรวจศาลาในป่าให้ที ฉันเชื่อว่าต้นเหตุอยู่ใต้ภูเขา');if(!w.accepted)add('รับคำขอของนารา','accept');if(w.cave&&!w.claimed){add('คืนหัวใจธาร · 60 เหรียญ','restore');add('ขายหัวใจธาร · 100 เหรียญ','sell');}}
 if(w.dialog==='lin'){text.textContent+='\nลิน: '+(w.companion?'ฉันจะเดินทางไปกับคุณ พักที่หมู่บ้านเพื่อฟื้นกำลังก่อนออกเดินทาง':'ฉันรู้จักเส้นทางในป่า ให้ฉันช่วยคุ้มกันไหม?');if(!w.companion)add('ชวนลินร่วมทาง','recruit',!w.accepted);}
 if(w.dialog==='ira')text.textContent+='\nอีรา: '+(w.learned?'ประกายชำระใช้เปิดผนึกได้ และใช้โจมตีในการต่อสู้บทนี้ได้ ฝึกใช้แล้วจะเกิดความชำนาญ':'อักษรที่ศาลาเป็นบันทึกเวทเก่า ลองอ่านเมื่อคุณไปถึง ไม่ใช่ทุกคนจะพบมัน');
 }else if(w.location==='forest'){text.textContent=w.forest?'คุณพบศาลาในช่องว่างระหว่างรากไม้ อักษรเรืองแสงบันทึกวิธีควบคุมประกายชำระ และชี้ทางไปถ้ำหัวใจธาร':'รอยเท้าผู้เฝ้ารากไม้อยู่บนทางหลัก คุณอาจอ้อมผ่านแนวพุ่มไม้ หรือเผชิญหน้ากับมัน';if(!w.forest){add('อ้อมตามร่องรอย · พลังงาน 10','scout');add('เผชิญผู้เฝ้ารากไม้','battle:forest');}else if(!w.learned)add('อ่านอักษรและเรียนประกายชำระ','learn');
 }else{text.textContent=w.cave?'ห้องผลึกสงบลง คุณได้หัวใจธารแล้ว กลับไปหานาราเพื่อตัดสินชะตาของลำธาร':w.seal?'ผนึกเปิดออก เงาผู้พิทักษ์ขยับอยู่รอบหัวใจธาร เตรียมทีมก่อนเข้าไป':'ม่านเวทปิดปากถ้ำ อักษรบนผนึกเป็นภาษาเดียวกับศาลาในป่า';if(!w.seal)add('ใช้ประกายชำระเปิดผนึก · 12 มานา','seal',!w.learned);else if(!w.cave)add('เข้าสู่ห้องหัวใจธาร','battle:cave');}
 text.style.whiteSpace='pre-line';panel.append(text,actions);const journal=document.createElement('p');journal.className='adventure-journal';journal.textContent=(w.companion?'เพื่อนร่วมทาง: ลิน · HP '+w.companion.hp+'/100':'ยังไม่มีเพื่อนร่วมทาง')+' · '+(w.learned?'ประกายชำระ · ความชำนาญ '+w.proficiency:'ยังไม่ค้นพบเวทของบทนี้')+(w.claimed?' · จบบทที่ 1':'');panel.append(journal);if(s.expedition){const resume=document.createElement('button');resume.textContent='เล่นการต่อสู้ที่บันทึกไว้ต่อ';resume.onclick=()=>EverTaleCombat.launch();panel.append(resume);}}
window.DecideAdventureUI={render:renderStory};})();
